# PTX source for a naive fp16 GEMM (M×K * K×N -> M×N) on SM80
PTX_SOURCE = r"""
.version 7.1
.target sm_80
.address_size 64

.visible .entry gemm_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // --------------------------------------------------------------------
    // Load kernel parameters
    // --------------------------------------------------------------------
    .reg .u64 %a_ptr, %b_ptr, %c_ptr;
    .reg .u32 %M, %N, %K;
    ld.param.u64 %a_ptr, [A_ptr];
    ld.param.u64 %b_ptr, [B_ptr];
    ld.param.u64 %c_ptr, [C_ptr];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // --------------------------------------------------------------------
    // Thread/block indices
    // --------------------------------------------------------------------
    .reg .u32 %tid_x, %tid_y;
    .reg .u32 %bid_x, %bid_y;
    .reg .u32 %row, %col;

    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;

    // each block processes a 16×16 tile
    mad.lo.u32 %col, %bid_x, 16, %tid_x;   // col = blockIdx.x * 16 + threadIdx.x
    mad.lo.u32 %row, %bid_y, 16, %tid_y;   // row = blockIdx.y * 16 + threadIdx.y

    // --------------------------------------------------------------------
    // Bounds check
    // --------------------------------------------------------------------
    .reg .pred %p0, %p1, %p2;
    setp.ge.u32 %p0, %row, %M;
    setp.ge.u32 %p1, %col, %N;
    or.pred %p2, %p0, %p1;
    @%p2 bra DONE;

    // --------------------------------------------------------------------
    // Accumulator (fp32)
    // --------------------------------------------------------------------
    .reg .f32 %acc;
    mov.f32 %acc, 0f00000000; // 0.0f

    // --------------------------------------------------------------------
    // Loop over K dimension
    // --------------------------------------------------------------------
    .reg .u32 %k;
    .reg .pred %p3;
    .reg .u64 %addrA, %addrB;
    .reg .f16 %a_half, %b_half;
    .reg .f32 %a_f32, %b_f32;

    mov.u32 %k, 0;

LOOP:
    setp.ge.u32 %p3, %k, %K;
    @%p3 bra END_LOOP;

    // addrA = &A[row, k]
    mul.wide.u32 %addrA, %row, %K;          // row*K
    add.u64 %addrA, %addrA, %a_ptr;        // base A
    mad.wide.u32 %addrA, %k, 2, %addrA;    // + k*2 (half is 2 bytes)

    // addrB = &B[k, col]
    mul.wide.u32 %addrB, %k, %N;           // k*N
    add.u64 %addrB, %addrB, %b_ptr;        // base B
    mad.wide.u32 %addrB, %col, 2, %addrB;  // + col*2

    // Load half‑precision elements
    ld.global.f16 %a_half, [%addrA];
    ld.global.f16 %b_half, [%addrB];

    // Convert to fp32
    cvt.f32.f16 %a_f32, %a_half;
    cvt.f32.f16 %b_f32, %b_half;

    // FMA: acc += a_f32 * b_f32
    fma.rn.f32 %acc, %a_f32, %b_f32, %acc;

    // k++
    add.u32 %k, %k, 1;
    bra LOOP;

END_LOOP:
    // --------------------------------------------------------------------
    // Write result (convert back to fp16)
    // --------------------------------------------------------------------
    cvt.rn.f16.f32 %a_half, %acc;   // reuse %a_half as output value

    // addrC = &C[row, col]
    mul.wide.u32 %addrA, %row, %N;   // row*N
    add.u64 %addrA, %addrA, %c_ptr; // base C
    mad.wide.u32 %addrA, %col, 2, %addrA; // + col*2

    st.global.f16 [%addrA], %a_half;

DONE:
    ret;
